diff --git a/crates/zero3-providers/src/weixin_clawbot.rs b/crates/zero3-providers/src/weixin_clawbot.rs
--- a/crates/zero3-providers/src/weixin_clawbot.rs
+++ b/crates/zero3-providers/src/weixin_clawbot.rs
@@ -291,8 +291,14 @@
             )),
             "binded_redirect" => {
+                let has_credentials = self.credentials.lock().await.is_some();
                 self.login_sessions.lock().await.remove(session_key);
+                if !has_credentials {
+                    return Err(anyhow!(
+                        "Weixin reports this bot is already bound, but local credentials are missing; reconnect after clearing the existing Weixin binding"
+                    ));
+                }
                 Ok(login_poll(
                     WeixinLoginState::AlreadyConnected,
                     true,
                     "此微信 ClawBot 已绑定",
                 ))
             }
